const sql=require("mssql"),mysql=require("mysql2/promise"),{getSourceConfig:getSourceConfig,getTargetConfig:getTargetConfig}=require("./db.helper");function turkishToEnglish(e){return e.replace(/ç/g,"c").replace(/ğ/g,"g").replace(/ı/g,"i").replace(/ö/g,"o").replace(/ş/g,"s").replace(/ü/g,"u").replace(/Ç/g,"C").replace(/Ğ/g,"G").replace(/İ/g,"I").replace(/Ö/g,"O").replace(/Ş/g,"S").replace(/Ü/g,"U")}async function migrateTenants(){let e,n;try{e=await sql.connect(getSourceConfig()),n=await mysql.createConnection(getTargetConfig());const a=(await e.request().query("SELECT * FROM SUBE WHERE Iptal = 0 AND ID > 0 ORDER BY ID")).recordset;if(0===a.length)return;for(const e of a){const a=turkishToEnglish(e.SubeAdi).toLowerCase().replace(/[^a-z0-9]/g,"-").replace(/-+/g,"-").slice(0,50),r="\n                INSERT INTO sys_tenants (\n                    name, \n                    phone, \n                    address, \n                    is_active, \n                    domain_prefix,\n                    created_at\n                ) VALUES (?, ?, ?, ?, ?, ?)\n                ON DUPLICATE KEY UPDATE \n                    name = VALUES(name),\n                    phone = VALUES(phone),\n                    address = VALUES(address),\n                    is_active = VALUES(is_active)\n            ",t=[e.SubeAdi,e.Telefonlar||null,e.Adresi||null,e.Iptal?0:1,a,e.SonKayitTarihi||new Date];await n.execute(r,t)}}catch(e){}finally{e&&await e.close(),n&&await n.end()}}migrateTenants();